import axios from 'axios'
import fetch from 'isomorphic-fetch'

class authApi {
  static async getCsrfReturnPayload(email) {
    let response = await fetch(`${process.env.API_URL  }/auth/signup`, {
      credentials: 'include',
    })
    response = await response.json()
    const payload = {
      email,
      _csrf: response.data.csrf.token,
    }
    return { payload }
  }

  static async checkEmailExistOrNot(data) {
    // const obj = await this.getCsrfReturnPayload(data)
    const response = await fetch(`${process.env.API_URL  }/auth/check-email`, {
      method: 'POST',
      body: JSON.stringify(data),
      credentials: 'include',
      headers: {
        Cookie: '',
      },
    })
    return response
  }

  static async teamInvitationAccept(token) {
    const response = await axios.get(
      `${process.env.API_URL}/team/invitation/accept/${token}`,
      {
        withCredentials: true,
      }
    )
    return response
    // response = await response.json()
  }
}
export default authApi
